const SERVICIOS = { EXP: 'express', STD: 'estandar' };

/** Del idioma del proveedor al del negocio. Si la forma no es la esperada, falla acá, en la frontera. */
export function traducir(raw) {
  const p = raw?.price;
  const ok = typeof p?.amt === 'string' && /^\d+(\.\d{1,2})?$/.test(p.amt) && p.cur === 'ARS'
    && /^\d+$/.test(raw.eta_days ?? '') && raw.svc in SERVICIOS;
  if (!ok) throw new ContratoRoto('forma inesperada, claves: ' + Object.keys(raw ?? {}).join(','));
  const [ent, dec = ''] = p.amt.split('.');
  return { servicio: SERVICIOS[raw.svc], centavos: Number(ent) * 100 + Number(dec.padEnd(2, '0')), moneda: 'ARS', dias: Number(raw.eta_days) };
}

export function crearAdaptador({ base, plazoMs = 600, intentos = 2, umbral = 3, enfriarMs = 5000, ttlMs = 600_000, tarifa, log = () => {} }) {
  let fallos = 0, abiertoHasta = 0;
  const cache = new Map();
  const medidas = { llamadas: 0, proveedor: 0, cache: 0, tarifa_propia: 0 };

  function degradar(clave, motivo) {
    const c = cache.get(clave);
    if (c && Date.now() - c.t < ttlMs) return { ...c.v, fuente: 'cache', motivo };
    return { ...tarifa(clave), fuente: 'tarifa_propia', motivo };
  }

  async function cotizar({ hasta, kg }) {
    const t0 = Date.now(), clave = `${hasta}|${kg}`;
    medidas.llamadas++;
    let r, motivo = 'desconocido';
    if (Date.now() < abiertoHasta) r = degradar(clave, 'circuito_abierto');
    else {
      for (let n = 1; n <= intentos && !r; n++) {
        try {
          const resp = await fetch(`${base}/v2/quote?to=${hasta}&kg=${kg}`, { signal: AbortSignal.timeout(plazoMs) });
          if (resp.status === 429) { motivo = '429'; await new Promise(ok => setTimeout(ok, Math.min(Number(resp.headers.get('retry-after') ?? 1) * 1000, 1000))); continue; }
          if (resp.status >= 500) { motivo = `http_${resp.status}`; continue; }
          if (!resp.ok) { motivo = `http_${resp.status}`; break; }          // un 4xx es culpa nuestra: reintentar no lo arregla
          const v = traducir(await resp.json());
          cache.set(clave, { v, t: Date.now() });
          fallos = 0; r = { ...v, fuente: 'proveedor' };
        } catch (e) {
          if (e instanceof ContratoRoto) { motivo = 'contrato_roto'; log({ nivel: 'error', motivo, detalle: e.message }); break; } // no tiene sentido repetir
          motivo = e.name === 'TimeoutError' ? 'timeout' : 'sin_conexion';
        }
      }
      if (!r) { if (++fallos >= umbral) abiertoHasta = Date.now() + enfriarMs; r = degradar(clave, motivo); }
    }
    medidas[r.fuente]++;
    log({ evento: 'cotizacion', fuente: r.fuente, motivo: r.motivo, ms: Date.now() - t0 });
    return r;
  }
  return { cotizar, medidas };
}

