// Un proveedor de cotizaciones simulado (datos inventados) y un adaptador mínimo.
const proveedores = {
  sano:   async () => ({ svc: 'EXP', price: { amt: '4900.00', cur: 'ARS' }, eta_days: '2' }),
  cambio: async () => ({ service: 'EXP', price: { amount_minor: 490000, currency: 'ARS' }, eta: { min: 1, max: 2 } }),
  lento:  () => new Promise(ok => setTimeout(() => ok({ svc: 'EXP', price: { amt: '4900.00', cur: 'ARS' }, eta_days: '2' }), 400)),
};

// Del idioma del proveedor al del negocio. Si la forma es otra, falla acá y no más adentro.
function traducir(raw) {
  const p = raw?.price;
  if (typeof p?.amt !== 'string' || p.cur !== 'ARS' || !/^\d+$/.test(raw.eta_days ?? '')) throw new Error('contrato_roto');
  const [ent, dec = ''] = p.amt.split('.');
  return { centavos: Number(ent) * 100 + Number(dec.padEnd(2, '0')), dias: Number(raw.eta_days) };
}

function crearAdaptador(llamar) {
  let ultima = null;                                    // lo último que salió bien
  return async function cotizar() {
    try {
      const raw = await Promise.race([llamar(), new Promise((_, no) => setTimeout(() => no(new Error('timeout')), 150))]);
      ultima = traducir(raw);
      return { ...ultima, fuente: 'proveedor' };
    } catch (e) {
      if (ultima) return { ...ultima, fuente: 'cache', motivo: e.message };
      return { centavos: 650000, dias: 5, fuente: 'tarifa_propia', motivo: e.message };
    }
  };
}

